How do you add these to chatgpt?<p>Chatgpt asks for a host for the mcp server.<p>All the MCPS I find give a config like<p>```{
  &quot;mcpServers&quot;: {
    &quot;sequential-thinking&quot;: {
      &quot;command&quot;: &quot;npx&quot;,
      &quot;args&quot;: [
        &quot;-y&quot;,
        &quot;@modelcontextprotocol&#x2F;server-sequential-thinking&quot;
      ]
    }
  }
}```

I use the AddService() method to inject a things on occasion but its not used heavily. For lightweight apps I&#x27;ll spin up things like a shared SQLiteConnection and inject it for all resources to use.<p>The DI pattern is simple &amp; clean at this scale. In my top-level program I define my routes like:<p><pre><code>  app.Map(&quot;&#x2F;&quot;, Home.HandleRequest);
  app.Map(&quot;&#x2F;login&quot;, Login.HandleRequest);
  app.Map(&quot;&#x2F;account&#x2F;new&quot;, NewAccount.HandleRequest);
  app.Map(&quot;&#x2F;{owner}&quot;, OwnerHome.HandleRequest);
</code></pre>
And then I have HandleRequest implementations like:<p><pre><code>  static async Task HandleRequest(HttpContext context, SQLiteConnection sql)
  static async Task HandleRequest(HttpContext context, SQLiteConnection sql, string owner)
  etc...
</code></pre>
The actual HandleRequest() method can do anything, including concerns like directly accepting and handling web socket connections.

Nice.<p>Here&#x27;s one from (the younger) me:<p><pre><code>  =======================
  Description
  =======================

  24-bit words (no bytes, so no endianness)

  &lt;op&gt; 5 &lt;dir&#x2F;ind&gt; 1 &lt;r1&#x2F;cond&gt; 3 &lt;r2&gt; 3 &lt;val&gt; 12
  r2 = 0 means zero value

  dir&#x2F;ind:

  0 dir
  1 ind

  cond:

  001 eq
  010 lt 
  1000 gt

  8 regs

  r0 = PC

  op:

  00x xx0 - type independent
  01x xx0 - bitwise
  10x xx0 - integer
  11x xx0 - floating-point

  ST 00 ; store (ignores ind&#x2F;dir)
  LD 02 ; load&#x2F;move
  BR 04 ; branch (rel&#x2F;abs)

  SL 20 ; shift left
  SR 22 ; shift right
  SA 24 ; shift right arithmetical
  OR 26 ; or
  AN 30 ; and
  OX 32 ; or exclusive (xor)
  NO 34 ; not

  AD 40 ; add
  SB 42 ; subtract
  MU 44 ; multiply
  DV 46 ; divide
  CP 50 ; compare

  FA 60 ; add
  FS 62 ; subtract
  FM 64 ; multiply
  FD 66 ; divide
  FC 70 ; compare

  example:

  LD r1, [4096] ; |03121000|
  AD r1, 1      ; |40100001|
  LD r2, r1     ; |02210000|
  SB r2, 33     ; |42200033|
  BR le, exit   ; |04300001|
  ST r1, [4096] ; |01201000|
  exit: .

  floating-point format - normalized:

  &lt;sign&gt; 1 &lt;exp&gt; 7 &lt;mantissa&gt; 16 + 1 implicit

  literals:

  decimal: -8,388,608 ... 8,388,607 (can use commas)
  binary (in octal): |42200033|
  floating-point: 1.23e-45
  character sequence &#x27;abc&#x27; (3 characters per word)

  r0 can be used as a temporary

  =======================
  Implementation
  =======================

  #include &lt;stdio.h&gt;
  #include &lt;ctype.h&gt;

  #define n 1024
  #define trace(op) fprintf(stderr, &quot;%04o %s\n&quot;, r0, #op)

  enum {
         ST = 000, &#x2F;* store (ignores ind&#x2F;dir) *&#x2F;
         LD = 002, &#x2F;* load&#x2F;move *&#x2F;
         BR = 004, &#x2F;* branch (ignores ind&#x2F;dir) *&#x2F;

         SL = 020, &#x2F;* shift left *&#x2F;
         SR = 022, &#x2F;* shift right *&#x2F;
         SA = 024, &#x2F;* shift right arithmetical *&#x2F;
         OR = 026, &#x2F;* or *&#x2F;
         AN = 030, &#x2F;* and *&#x2F;
         OX = 032, &#x2F;* or exclusive (xor) *&#x2F;
         NO = 034, &#x2F;* not *&#x2F;

         AD = 040, &#x2F;* add *&#x2F;
         SB = 042, &#x2F;* subtract *&#x2F;
         MU = 044, &#x2F;* multiply *&#x2F;
         DV = 046, &#x2F;* divide *&#x2F;
         CP = 050, &#x2F;* compare *&#x2F;

         FA = 060, &#x2F;* add *&#x2F;
         FS = 062, &#x2F;* subtract *&#x2F;
         FM = 064, &#x2F;* multiply *&#x2F;
         FD = 066, &#x2F;* divide *&#x2F;
         FC = 070 &#x2F;* compare *&#x2F;
  };

  int main() {
         static int b[n];
         &#x2F;* load image *&#x2F;
         int c, *p, s, z;
         static int r[8];
         for (s = 21, p = b; p &lt; b + n &amp;&amp; (c = getchar()) &gt; 0;)
                 if (isdigit(c) &amp;&amp; c &lt;= &#x27;7&#x27;) {
                         *p |= (~0x30 &amp; c) &lt;&lt; s;
                         if (s)
                                 s -=3;
                         else
                                 s = 21, ++p;
                 }
         &#x2F;* run image *&#x2F;
         c = 7;
         while (r[0] &gt;= 0 &amp;&amp; r[0] &lt; n) {
                 int i, o, d, x, y, v, r0;
                 i = b[r0 = r[0]++]; &#x2F;* inc PC *&#x2F;
                 o = (i &gt;&gt; 19 &amp; 31) &lt;&lt; 1;
                 d = !(i &gt;&gt; 18 &amp; 1);
                 x = i &gt;&gt; 15 &amp; 7;
                 y = i &gt;&gt; 12 &amp; 7;
                 v = ((i &lt;&lt; 20) &gt;&gt; 20) + (y ? r[y] : 0); &#x2F;* assuming 32-bit ints *&#x2F;
                 switch(o) {
                         case ST: b[v] = r[x]; trace(ST); break;
                         case LD: r[x] = d ? v : b[v]; trace(LD); break;
                         case BR: if (x &amp; c) r[0] += v; trace(BR); break;
                         case SL: r[x] &lt;&lt;= v; c = r[x] == 0 ? 1 : r[x] &lt; 0 ? 2 : 4; trace(SL); break;
                         case SR: r[x] &gt;&gt; v; c = r[x] == 0 ? 1 : r[x] &lt; 0 ? 2 : 4; trace(SR); break;
                         case SA: r[x] &gt;&gt; (unsigned) v; c = r[x] == 0 ? 1 : r[x] &lt; 0 ? 2 : 4; trace(SA); break;
                         case OR: r[x] |= (d ? v : b[v]); c = r[x] == 0 ? 1 : r[x] &lt; 0 ? 2 : 4; trace(OR); break;
                         case AN: r[x] &amp;= (d ? v : b[v]); c = r[x] == 0 ? 1 : r[x] &lt; 0 ? 2 : 4; trace(AN); break;
                         case OX: r[x] ^= (d ? v : b[v]); c = r[x] == 0 ? 1 : r[x] &lt; 0 ? 2 : 4; trace(OX); break;
                         case NO: r[x] = ~r[x]; c = r[x] == 0 ? 1 : r[x] &lt; 0 ? 2 : 4; trace(NO); break;
                         case AD: r[x] += (d ? v : b[v]); c = r[x] == 0 ? 1 : r[x] &lt; 0 ? 2 : 4; trace(AD); break; 
                         case SB: r[x] -= (d ? v : b[v]); c = r[x] == 0 ? 1 : r[x] &lt; 0 ? 2 : 4; trace(SB); break;
                         case MU: r[x] *= (d ? v : b[v]); c = r[x] == 0 ? 1 : r[x] &lt; 0 ? 2 : 4; trace(MU); break;
                         case DV: r[x + 1] = r[x] % (d ? v : b[v]); r[x] &#x2F;= (d ? v : b[v]); c = r[x] == 0 ? 1 : r[x] &lt; 0 ? 2 : 4; trace(DV); break;
                         case CP: c = r[x] == (d ? v : b[v]) ? 1 : r[x] &lt; (d ? v : b[v]) ? 2 : 4; trace(CP); break;
                         case FA: trace(FA); break; &#x2F;* TODO *&#x2F;
                         case FS: trace(FS); break; &#x2F;* TODO *&#x2F;
                         case FM: trace(FM); break; &#x2F;* TODO *&#x2F;
                         case FD: trace(FD); break; &#x2F;* TODO *&#x2F;
                         case FC: trace(FC); break; &#x2F;* TODO *&#x2F;
                 }
         }
         &#x2F;* print image *&#x2F;
         for (z = 0, p = b; p &lt; b + n; ++p) 
                 if (*p) {
                         int m;
                         if (z) {
                                 puts(&quot;00000000&quot;);
                                 if (z &gt; 3)
                                         puts(&quot;........&quot;);
                                 else if (z &gt; 1)
                                         puts(&quot;00000000&quot;);
                                 if (z &gt; 2)                      
                                         puts(&quot;00000000&quot;);
                                 z = 0;
                         }
                         for (s = 21, m = 7 &lt;&lt; s; m; m &gt;&gt;= 3, s -= 3)
                                 putchar(0x30 | (*p &amp; m) &gt;&gt; s);
                         putchar(&#x27;\n&#x27;);
                 }
                 else
                         ++z;
         return 0;
  }

